"""Historical ASGD source verification through full pretrained Qwen3.5 LoRA SFT."""
import argparse,hashlib,importlib.util,json,math,os,sys,time
from pathlib import Path
import torch

def load_source(root,kind):
 p=root/(kind+'_asgd.py');name='torch.optim._precision_real_'+kind;spec=importlib.util.spec_from_file_location(name,p);module=importlib.util.module_from_spec(spec);sys.modules[name]=module;spec.loader.exec_module(module);return module

def check_schedule(module,foreach,device):
 p=torch.nn.Parameter(torch.tensor([.5,-.25],device=device));opt=module.ASGD([p],lr=.2,lambd=.01,alpha=.75,t0=1,foreach=foreach);errors=[]
 for step in range(1,4):
  p.grad=torch.tensor([.1,-.2],device=device);opt.step();errors.append(abs(float(opt.state[p]['eta'])-.2/(1+.01*.2*step)**.75))
 return errors

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--root',required=True);ap.add_argument('--output',required=True);a=ap.parse_args();root=Path(a.root);out=Path(a.output);out.mkdir(parents=True,exist_ok=False);card=json.loads((root/'resources.json').read_text());modelpath=card['models'][0]['path'];start=time.monotonic();torch.manual_seed(1729);torch.set_num_threads(8);torch.backends.cuda.matmul.allow_tf32=False
 from transformers import AutoModelForCausalLM,AutoTokenizer
 from peft import LoraConfig,get_peft_model
 sys.path.insert(0,'/home/jovyan/projects/precision-skills/skills/precision-compare/scripts')
 from array_compare import compare_arrays
 tokenizer=AutoTokenizer.from_pretrained(modelpath,local_files_only=True)
 model=AutoModelForCausalLM.from_pretrained(modelpath,torch_dtype=torch.bfloat16,attn_implementation='eager',local_files_only=True).to('cuda')
 native_parameter_count=sum(p.numel() for p in model.parameters());native_layers=model.config.num_hidden_layers
 model=get_peft_model(model,LoraConfig(r=4,lora_alpha=8,lora_dropout=0.,target_modules=['q_proj','v_proj'],bias='none',task_type='CAUSAL_LM'));model.config.use_cache=False
 trainable={n:p for n,p in model.named_parameters() if p.requires_grad};assert trainable and all(p.dtype==torch.float32 for p in trainable.values());initial={n:p.detach().cpu().clone() for n,p in trainable.items()}
 texts=['The capital of France is Paris. Explain why the city is important in European history.','A neural network learns by updating its parameters to reduce the training objective.','Water freezes at zero degrees Celsius under standard atmospheric pressure.']
 batches=[tokenizer(s,return_tensors='pt',truncation=True,max_length=40).to('cuda') for s in texts];input_evidence=[{'text':s,'input_ids':b['input_ids'][0].tolist()} for s,b in zip(texts,batches)]
 sources={k:load_source(root,k) for k in ['affected','candidate']};schedule={k:check_schedule(sources['candidate' if k=='candidate' else 'affected'],k!='control','cuda') for k in ['affected','candidate','control']};rows={};arrays={};configs={}
 for kind in ['control','affected','candidate']:
  torch.manual_seed(1729)
  with torch.no_grad():
   for n,p in trainable.items():p.copy_(initial[n])
  model.zero_grad(set_to_none=True);module=sources['candidate' if kind=='candidate' else 'affected'];opt=module.ASGD(list(trainable.values()),lr=.2,lambd=.01,alpha=.75,t0=1,foreach=kind!='control');trace=[];views={};dispatch={'single':0,'foreach':0}
  def profiler(frame,event,arg):
   if event=='call' and frame.f_code.co_filename==module.__file__:
    if frame.f_code.co_name=='_single_tensor_asgd':dispatch['single']+=1
    elif frame.f_code.co_name=='_multi_tensor_asgd':dispatch['foreach']+=1
  model.train()
  for step,batch in enumerate(batches,1):
   before={n:p.detach().cpu().clone() for n,p in trainable.items()};opt.zero_grad(set_to_none=True);loss=model(**batch,labels=batch['input_ids'],use_cache=False).loss;assert torch.isfinite(loss);loss.backward();grads={n:p.grad.detach().cpu().clone() for n,p in trainable.items() if p.grad is not None};assert len(grads)==len(trainable);sys.setprofile(profiler)
   try:opt.step()
   finally:sys.setprofile(None)
   eta_expected=.2/(1+.01*.2*step)**.75;eta_errors=[]
   for n,p in trainable.items():
    state=opt.state[p];eta_errors.append(abs(float(state['eta'])-eta_expected));views[f'step{step}/parameter/{n}']=p.detach().cpu().numpy().copy();views[f'step{step}/gradient/{n}']=grads[n].numpy();views[f'step{step}/update/{n}']=(p.detach().cpu()-before[n]).numpy();views[f'step{step}/average/{n}']=state['ax'].detach().cpu().numpy().copy()
   trace.append({'step':step,'loss':float(loss),'targets':int(batch['input_ids'].numel()-1),'parameters_with_gradient':len(grads),'expected_next_eta':eta_expected,'maximum_eta_absolute_error':max(eta_errors)})
  model.eval();evaluation=[]
  with torch.inference_mode():
   for i,b in enumerate(batches):
    logits=model(**b,use_cache=False).logits;lp=torch.log_softmax(logits[0,:-1].float(),-1).gather(1,b['input_ids'][0,1:,None]).flatten().cpu();evaluation.append({'sample':i,'target_logprobs':lp.tolist(),'nll':float(-lp.double().mean())})
  torch.save({'trainable':{n:p.detach().cpu() for n,p in trainable.items()},'optimizer':opt.state_dict(),'rng':torch.get_rng_state(),'step':3,'views':views},out/(kind+'-training.pt'));rows[kind]={'steps':trace,'evaluation':evaluation,'dispatch':dispatch};arrays[kind]=views;configs[kind]={'foreach':kind!='control','source_sha256':hashlib.sha256(Path(module.__file__).read_bytes()).hexdigest()};print(json.dumps({'branch':kind,'trace':trace,'dispatch':dispatch}),flush=True)
  del opt
 comparison={k:compare_arrays(arrays['control'],arrays[k],metrics=True,groups={f'step{s}':[key for key in arrays[k] if key.startswith(f'step{s}/')] for s in range(1,4)}) for k in ['affected','candidate']}
 # Domain assertions are on the declared schedule and original training path.
 assert max(schedule['affected'])>1e-5 and max(schedule['candidate'])<2e-8 and max(schedule['control'])<2e-8,schedule
 for k in ['control','candidate']:assert max(s['maximum_eta_absolute_error'] for s in rows[k]['steps'])<2e-8
 def max_diff(kind,field):return max(float(abs(arrays[kind][key]-arrays['control'][key]).max()) for key in arrays[kind] if '/'+field+'/' in key)
 maxima={kind:{field:max_diff(kind,field) for field in ['parameter','gradient','update','average']} for kind in ['affected','candidate']};assert maxima['affected']['parameter']>10*max(maxima['candidate']['parameter'],1e-9),maxima
 import importlib.metadata as md
 summary={'classification':'historical_source_backport_real_pretrained_model_verification','model':{'name':'Qwen3.5-9B-Base','revision':card['models'][0]['revision'],'full_native_parameter_count':native_parameter_count,'native_layers':native_layers,'trainable_parameter_count':sum(p.numel() for p in trainable.values()),'trainable_tensors':len(trainable),'adapter':'LoRA rank 4, alpha 8, dropout 0, q_proj/v_proj, FP32 adapters','base_dtype':'bfloat16'},'runtime':{'packages':{n:md.version(n) for n in ['torch','transformers','peft']},'gpu':torch.cuda.get_device_name(0),'total_memory':torch.cuda.get_device_properties(0).total_memory},'hyperparameters':{'lr':.2,'lambd':.01,'alpha':.75,'t0':1,'weight_decay':0},'inputs':input_evidence,'branches':rows,'sources':configs,'schedule_errors':schedule,'maximum_absolute_differences':maxima,'comparisons':comparison,'elapsed_seconds':time.monotonic()-start,'coverage':{'branches':3,'steps_per_branch':3,'all_trainable_tensors_have_gradients':True},'checks':{'isolated_affected_schedule_fails':True,'patched_schedule_passes':True,'single_tensor_schedule_passes':True,'original_full_model_sft_verified':True,'installed_libraries_modified':False}}
 (out/'summary.json').write_text(json.dumps(summary,indent=2,allow_nan=False)+'\n');print(json.dumps({'status':'completed','maxima':maxima,'output':str(out)}))
if __name__=='__main__':main()

