"""Regression for the historical schedule, alongside full-model validation."""
import unittest,os
from pathlib import Path
from train_real import load_source,check_schedule
class ScheduleTests(unittest.TestCase):
    def test_patched_schedule_and_native_single_tensor(self):
        root=Path(__file__).resolve().parent
        for source,foreach in [('candidate',True),('affected',False)]:
            with self.subTest(source=source,foreach=foreach):
                self.assertLess(max(check_schedule(load_source(root,source),foreach,'cpu')),2e-8)
    def test_foreach_follows_the_declared_schedule(self):
        source=os.environ.get('PRECISION_ASGD_SOURCE','candidate')
        self.assertLess(max(check_schedule(load_source(Path(__file__).resolve().parent,source),True,'cpu')),2e-8)
    def test_affected_foreach_violates_formula(self):
        self.assertGreater(max(check_schedule(load_source(Path(__file__).resolve().parent,'affected'),True,'cpu')),1e-5)
if __name__=='__main__':unittest.main()
